style.css:
@-moz-document domain("finn.no") {
/* Grunnleggende */
  :root, html, body {
    color-scheme: dark !important;
    background-color: #000 !important;
    color: #fff !important;
  }

  /* Tekst */
  body, main, section, article, aside, header, footer, nav,
  div, span, p, li, dt, dd, th, td, h1, h2, h3, h4, h5, h6,
  a, a span, a svg, a .s-text-static {
    color: #fff !important;
    background-color: transparent !important;
  }

  /* Større containere */
  html, body, main, section, article, aside, header, footer, nav,
  [class*="Card"], [class*="card"], [class*="box"], [class*="panel"],
  [class*="container"], [class*="sheet"], [class*="modal"],
  [class*="dropdown"], [class*="popover"], [class*="tooltip"] {
    background-color: #000 !important;
    background-image: none !important;
  }

  /* Topbar / søk */
  header, [id*="topbar"], [class*="Topbar"], [class*="Header"], [class*="search"], .topbar, .header {
    background-color: #111 !important;
    color: #fff !important;
  }

  /* Input / søkefelt */
  input, textarea, select {
    background-color: #111 !important;
    color: #fff !important;
    border: 1px solid #333 !important;
  }
  input::placeholder, textarea::placeholder { color: #bbb !important; }

  /* Knapper */
  button, [role="button"], a[role="button"], .button, .btn, a.button, input[type="button"], input[type="submit"] {
    background-color: #111 !important;
    color: #fff !important;
    border: 1px solid #2a2a2a !important;
  }
  button:hover, [role="button"]:hover, .button:hover, a.button:hover, .btn:hover {
    background-color: #222 !important;
    color: #fff !important;
  }

  /* SVG-ikoner */
  svg, svg * {
    fill: #fff !important;
    stroke: #fff !important;
    color: #fff !important;
  }

  /* FINN custom icon-classes (s-icon etc.) */
  [class*="s-icon"], [class*="s-icon-"], [class*="icon"], [class*="Icon"] {
    color: #fff !important;
    fill: #fff !important;
    stroke: #fff !important;
  }

  /* Ikoner i lenker med data-icon-name attribute (kategori-lenker) */
  a[data-icon-name] svg,
  a[data-icon-name] .s-icon,
  a[data-icon-name] .s-icon-secondary,
  a[data-icon-name] .s-text-static {
    color: #fff !important;
    fill: #fff !important;
    stroke: #fff !important;
  }

  /* Tekstklasser */
  .s-text-static, .s-text-subtle, .s-text-muted, .s-text {
    color: #fff !important;
  }

  /* Border / outline */
  *, *::before, *::after {
    border-color: #2a2a2a !important;
    outline-color: #3a3a3a !important;
  }

  /* Scrollbar (webkit) */
  *::-webkit-scrollbar { width: 10px; height: 10px; }
  *::-webkit-scrollbar-track { background: #000; }
  *::-webkit-scrollbar-thumb { background: #2a2a2a; border-radius: 6px; }
  *::-webkit-scrollbar-thumb:hover { background: #3a3a3a; }

  /* Ikke endre bilder/annonser */
  img, picture, video, canvas, iframe, [class*="ad-"], [id*="ad-"] {
    filter: none !important;
    mix-blend-mode: normal !important;
    background: transparent !important;
  }

  /* Sikkerhetsregel for lenker med ikon */
  a[data-icon-name], a[data-icon-name] span, a[data-icon-name] svg {
    color: #fff !important;
    fill: #fff !important;
    stroke: #fff !important;
  }
}
